```c
/**
 * Returns the number of rows needed for a KV cache of capacity `cap`
 * to store a sequence of `len` tokens. Returns 0 if either argument is non-positive.
 */
int kv_rows_needed(int len, int cap) {
    if (len <= 0 || cap <= 0) return 0;
    return len < cap ? len : cap;
}
